import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { selfChartPutWire } from '/Users/chiburashka/.codex/worktrees/4806/site/src/lib/account-v2/chart-wire.ts';
import { parseReadyRemoteChart } from '/Users/chiburashka/.codex/worktrees/4806/site/src/lib/account-v2/remote-chart.ts';
import { parseAccountSyncInput, parseSerializedAccountPrivateChartPayload } from '/Users/chiburashka/.codex/worktrees/4806/site/src/lib/account-api/sync-wire.ts';
import { serializePrivateChartPayloadV1, putChartMutationFingerprintV1 } from '/Users/chiburashka/.codex/worktrees/4806/site/src/lib/account-v2/mutation-fingerprint.ts';
import { POSITION_BODY_ORDER } from '/Users/chiburashka/.codex/worktrees/4806/site/src/lib/share-positions.ts';

const uuid='11111111-1111-4111-8111-111111111111';
const chart:any={id:uuid,name:'Synthetic compatibility',createdAt:'2026-01-01T00:00:00.000Z',updatedAt:'2026-01-01T00:00:00.000Z',birth:{date:'2001-12-21',time:'09:00',timeKnown:true,place:{name:'Synthetic place',admin1:'',country:'',lat:78.2232,lon:15.6267,tz:'Etc/UTC'}},summary:{engineVersion:'synthetic-v1',utcISO:'2001-12-21T09:00:00.000Z',houseSystem:'whole',bodies:POSITION_BODY_ORDER.map((body,index)=>({body,lon:index*20,retrograde:false})),angles:{asc:42,mc:140},flags:['polar-fallback']}};
const request=(body:any)=>({headers:{'content-type':'application/json'},body});
const wire=selfChartPutWire(chart,uuid,uuid,3)!;
assert.ok(wire);
assert.ok(parseAccountSyncInput('chart-put',request(wire)));
const raw=serializePrivateChartPayloadV1(wire);
assert.ok(parseSerializedAccountPrivateChartPayload(raw));
const hasExtraBirth={...wire,birth:{...wire.birth,requestedHouseSystem:'placidus'}};
const hasExtraDerived={...wire,derived:{...wire.derived,requestedHouseSystem:'placidus'}};
assert.equal(parseAccountSyncInput('chart-put',request(hasExtraBirth)),null);
assert.equal(parseAccountSyncInput('chart-put',request(hasExtraDerived)),null);
assert.equal(serializePrivateChartPayloadV1(hasExtraBirth),raw);
assert.equal(serializePrivateChartPayloadV1(hasExtraDerived),raw);
assert.equal(parseSerializedAccountPrivateChartPayload(JSON.stringify({...JSON.parse(raw),schema:'zodiacs.account.private-chart.v2'})),null);
const plainWithExtra=JSON.parse(raw);plainWithExtra.derived.requestedHouseSystem='placidus';
assert.equal(parseSerializedAccountPrivateChartPayload(JSON.stringify(plainWithExtra)),null);
const remote={outcome:'ready',chart_id:uuid,label:wire.label,subject_kind:'self',subject_attestation:'self_declared_v1',revision:4,created_at:chart.createdAt,updated_at:chart.updatedAt,birth:wire.birth,derived:{positions:wire.derived.positions,time_known:wire.derived.timeKnown,sun_sign:wire.derived.sunSign,engine_version:wire.derived.engineVersion,house_system:wire.derived.houseSystem}};
assert.ok(parseReadyRemoteChart(remote));
assert.equal(parseReadyRemoteChart({...remote,derived:{...remote.derived,requested_house_system:'placidus'}}),null);
const fallbackResave=structuredClone(chart);fallbackResave.summary.requestedHouseSystem='placidus';
const explicitWhole=structuredClone(chart);explicitWhole.summary.requestedHouseSystem='whole';explicitWhole.summary.flags=[];
const oldFallbackWire=selfChartPutWire(fallbackResave,uuid,uuid,3)!;
const oldExplicitWire=selfChartPutWire(explicitWhole,uuid,uuid,3)!;
assert.deepEqual(oldFallbackWire,oldExplicitWire);
assert.equal(serializePrivateChartPayloadV1(oldFallbackWire),serializePrivateChartPayloadV1(oldExplicitWire));
const fingerprint=await putChartMutationFingerprintV1(oldFallbackWire);
assert.equal(fingerprint,await putChartMutationFingerprintV1(oldExplicitWire));
const report={schemaVersion:1,observedAt:new Date().toISOString(),node:process.version,scope:'Pure local calls using synthetic values; no request, account, storage or source mutation.',baseline:{wireAccepted:true,plaintextAccepted:true,readyProjectionAccepted:true},extensions:{birthExtraRejected:true,derivedExtraRejected:true,plaintextExtraRejected:true,plaintextV2RejectedByV1:true,readyExtraRejected:true,serializerDropsExtraBirth:true,serializerDropsExtraDerived:true},indistinguishableOldWrites:{fallbackOriginalRequest:'placidus',explicitNewRequest:'whole',actualSystemForBoth:'whole',oldWiresIdentical:true,canonicalBytesIdentical:true,mutationFingerprintsIdentical:true,fingerprint},conclusion:'An unchanged old-client write cannot identify whether retained richer request metadata should survive or be replaced. Use a version-aware safe downgrade/write policy, not inference.'};
writeFileSync('/private/tmp/zodiacs-platform-c02-remote/compatibility-boundary.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report,null,2));
